def is_not_prime(n: int) -> bool:
    """
    Return True if n is not a prime number, False if n is prime.
    By definition, numbers less than 2 are not prime.
    """
    if n < 2:
        return True
    if n == 2:
        return False
    if n % 2 == 0:
        return True
    # Check odd divisors up to sqrt(n)
    limit = int(n**0.5) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return True
    return False
